import { expect } from 'chai';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

// Load the implementation under test from the workspace root so this test
// works regardless of where the runner places this file.
const { default: flattenTokens } = await import(
  pathToFileURL(join(process.cwd(), 'lib/utils/flattenTokens.js')).href
);

function makeTokens() {
  return {
    color: {
      red: {
        value: { r: 255, g: 0, b: 0 },
        attributes: { category: 'color', type: 'composite' },
        original: { value: { r: 255, g: 0, b: 0 } },
        path: ['color', 'red'],
        comment: 'the red one',
      },
      green: {
        value: { r: 0, g: 255, b: 0 },
        attributes: { category: 'color', type: 'composite' },
        original: { value: { r: 0, g: 255, b: 0 } },
        path: ['color', 'green'],
        comment: 'the green one',
      },
    },
    spacing: {
      base: {
        value: { size: 4, unit: 'px' },
        attributes: { category: 'spacing' },
        original: { value: { size: 4, unit: 'px' } },
        path: ['spacing', 'base'],
      },
    },
  };
}

function makeDtcgTokens() {
  return {
    color: {
      red: {
        $value: { r: 255, g: 0, b: 0 },
        $type: 'color',
        attributes: { category: 'color' },
        original: { $value: { r: 255, g: 0, b: 0 } },
        path: ['color', 'red'],
      },
    },
    spacing: {
      base: {
        $value: { size: 4, unit: 'px' },
        $type: 'dimension',
        attributes: { category: 'spacing' },
        original: { $value: { size: 4, unit: 'px' } },
        path: ['spacing', 'base'],
      },
    },
  };
}

describe('flattenTokens leaves the input deeply unchanged', () => {
  it('does not modify a non-DTCG tokens object', () => {
    const tokens = makeTokens();
    const before = structuredClone(tokens);
    flattenTokens(tokens);
    expect(tokens).to.eql(before);
  });

  it('does not add the generated key property onto the input tokens', () => {
    const tokens = makeTokens();
    flattenTokens(tokens);
    expect(tokens.color.red).to.not.have.property('key');
    expect(tokens.color.green).to.not.have.property('key');
    expect(tokens.spacing.base).to.not.have.property('key');
  });

  it('does not modify a DTCG tokens object', () => {
    const tokens = makeDtcgTokens();
    const before = structuredClone(tokens);
    flattenTokens(tokens, true);
    expect(tokens).to.eql(before);
  });

  it('leaves the input unchanged across repeated calls that produce equal results', () => {
    const tokens = makeTokens();
    const before = structuredClone(tokens);
    const first = flattenTokens(tokens);
    const second = flattenTokens(tokens);
    expect(tokens).to.eql(before);
    expect(second).to.eql(first);
  });
});

