        attributes: { category: 'color' },
        original: { $value: { r: 255, g: 0, b: 0 } },
        path: ['color', 'red'],
      },
    },
    spacing: {
      base: {
        $value: { size: 4, unit: 'px' },
        $type: 'dimension',
        attributes: { category: 'spacing' },
        original: { $value: { size: 4, unit: 'px' } },
        path: ['spacing', 'base'],
      },
    },
  };
