describe('flattenTokens returned tokens share no nested structures with the input', () => {
  it('returns tokens whose nested objects and arrays are distinct from the input token', () => {
    const tokens = makeTokens();
    const result = flattenTokens(tokens);
    const red = result[0];
    const source = tokens.color.red;

    expect(red).to.not.equal(source);
    expect(red.value).to.not.equal(source.value);
    expect(red.attributes).to.not.equal(source.attributes);
    expect(red.original).to.not.equal(source.original);
    expect(red.path).to.not.equal(source.path);
  });

  it('returns a token that still carries all of the original token data', () => {
    const tokens = makeTokens();
    const red = flattenTokens(tokens)[0];

    expect(red.key).to.eql('{color.red}');
    expect(red.value).to.eql({ r: 255, g: 0, b: 0 });
    expect(red.attributes).to.eql({ category: 'color', type: 'composite' });
    expect(red.original).to.eql({ value: { r: 255, g: 0, b: 0 } });
    expect(red.path).to.eql(['color', 'red']);
    expect(red.comment).to.eql('the red one');
  });

  it('mutating nested sub-properties of a returned token leaves the input unchanged', () => {
    const tokens = makeTokens();
    const before = structuredClone(tokens);
    const result = flattenTokens(tokens);
    const red = result.find((t) => t.key === '{color.red}');

    red.value.r = 1;
    red.value.injected = true;
    red.attributes.category = 'mutated';
    red.original.value.r = 42;
    red.path.push('mutated');

    expect(tokens).to.eql(before);
  });

  it('mutating the input afterwards does not change previously returned tokens', () => {
    const tokens = makeTokens();
    const result = flattenTokens(tokens);
    const before = structuredClone(result);

    tokens.color.red.value.r = 9;
    tokens.color.red.attributes.category = 'changed';
    tokens.color.red.original.value.r = 9;
    tokens.color.red.path.push('changed');
    tokens.color.green.value.g = 9;
    tokens.color.green.attributes.type = 'changed';

    expect(result).to.eql(before);
  });

  it('sibling returned tokens do not share nested structures with each other', () => {
    const result = flattenTokens(makeTokens());
    expect(result.length).to.eql(3);
    const red = result[0];
    const green = result[1];

    expect(red.attributes).to.not.equal(green.attributes);
    expect(red.value).to.not.equal(green.value);
    expect(red.original).to.not.equal(green.original);
    expect(red.path).to.not.equal(green.path);
  });

  it('DTCG returned tokens can be mutated without changing the input', () => {
    const tokens = makeDtcgTokens();
    const before = structuredClone(tokens);
    const result = flattenTokens(tokens, true);
    const red = result.find((t) => t.key === '{color.red}');
    const source = tokens.color.red;

    expect(red.$value).to.not.equal(source.$value);
    expect(red.attributes).to.not.equal(source.attributes);
    expect(red.original).to.not.equal(source.original);
    expect(red.path).to.not.equal(source.path);

    red.$value.r = 3;
    red.attributes.category = 'mutated';
    red.path.push('mutated');

    expect(tokens).to.eql(before);
  });

  it('DTCG: mutating the input afterwards does not change previously returned tokens', () => {
    const tokens = makeDtcgTokens();
    const result = flattenTokens(tokens, true);
    const before = structuredClone(result);

    tokens.color.red.$value.r = 5;
    tokens.color.red.attributes.category = 'changed';
    tokens.color.red.path.push('changed');

    expect(result).to.eql(before);
  });
});

import { expect } from 'chai';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

// Load the implementation under test from the workspace root so this test
// works regardless of where the runner places this file.
const { convertTokenData } = await import(
  pathToFileURL(join(process.cwd(), 'lib/utils/convertTokenData.js')).href
);

const INPUTS = ['object', 'map', 'array'];
const OUTPUTS = ['object', 'map', 'array'];

function makeObject() {
  return {
    color: {
      red: {
        value: { r: 255, g: 0, b: 0 },
        attributes: { category: 'color' },
        original: { value: { r: 255, g: 0, b: 0 } },
        path: ['color', 'red'],
        key: '{color.red}',
      },
      green: {
        value: { r: 0, g: 255, b: 0 },
        attributes: { category: 'color' },
        original: { value: { r: 0, g: 255, b: 0 } },
        path: ['color', 'green'],
        key: '{color.green}',
      },
    },
    spacing: {
      base: {
        value: { size: 4, unit: 'px' },
        attributes: { category: 'spacing' },
        original: { value: { size: 4, unit: 'px' } },
        path: ['spacing', 'base'],
        key: '{spacing.base}',
      },
    },
  };
}

function makeArray() {
  const object = makeObject();
  return [object.color.red, object.color.green, object.spacing.base];
}

function makeMap() {
  return new Map(makeArray().map((token) => [token.key, token]));
}

function makeDtcgObject() {
  return {
    color: {
      red: {
        $value: { r: 255, g: 0, b: 0 },
        attributes: { category: 'color' },
        original: { $value: { r: 255, g: 0, b: 0 } },
        path: ['color', 'red'],
        key: '{color.red}',
      },
      green: {
        $value: { r: 0, g: 255, b: 0 },
        attributes: { category: 'color' },
        original: { $value: { r: 0, g: 255, b: 0 } },
        path: ['color', 'green'],
        key: '{color.green}',
      },
    },
    spacing: {
      base: {
        $value: { size: 4, unit: 'px' },
        attributes: { category: 'spacing' },
        original: { $value: { size: 4, unit: 'px' } },
        path: ['spacing', 'base'],
        key: '{spacing.base}',
      },
    },
  };
}

const FACTORIES = { object: makeObject, map: makeMap, array: makeArray };

// Collect every token contained in a collection of any of the 3 supported shapes.
function tokensIn(collection, type) {
  if (type === 'array') {
    return collection.slice();
  }
  if (type === 'map') {
    return Array.from(collection.values());
  }
  const found = [];
  const walk = (node) => {
    if (node === null || typeof node !== 'object') {
      return;
    }
    if (Object.hasOwn(node, 'value') || Object.hasOwn(node, '$value')) {
      found.push(node);
      return;
    }
    for (const k of Object.keys(node)) {
      walk(node[k]);
    }
  };
  for (const k of Object.keys(collection)) {
    walk(collection[k]);
  }
  return found;
}

// Mutate nested sub-properties of a token the way an accidental caller would.
function mutateNested(token) {
  for (const prop of ['value', '$value', 'attributes', 'original', 'path']) {
    const nested = token[prop];
    if (Array.isArray(nested)) {
      nested.push('mutated');
    } else if (nested !== null && typeof nested === 'object') {
      nested.injected = 'mutated';
    }
  }
}

describe('convertTokenData leaves its input deeply unchanged for every combination', () => {
  INPUTS.forEach((input) => {
    OUTPUTS.forEach((output) => {
      it(`${input} -> ${output}: the conversion call itself does not modify the input`, () => {
        const tokens = FACTORIES[input]();
        const before = structuredClone(tokens);
        convertTokenData(tokens, { output, usesDtcg: false });
        expect(tokens).to.eql(before);
      });

      it(`${input} -> ${output}: mutating every returned token does not modify the input`, () => {
        const tokens = FACTORIES[input]();
        const before = structuredClone(tokens);
        const result = convertTokenData(tokens, { output, usesDtcg: false });
        tokensIn(result, output).forEach(mutateNested);
        expect(tokens).to.eql(before);
      });
    });
  });

  it('object (DTCG) -> map: mutating every returned token does not modify the input', () => {
    const tokens = makeDtcgObject();
    const before = structuredClone(tokens);
    const result = convertTokenData(tokens, { output: 'map', usesDtcg: true });
    expect(result).to.be.instanceOf(Map);
    expect(result.size).to.eql(3);
    Array.from(result.values()).forEach(mutateNested);
    expect(tokens).to.eql(before);
  });

  it('object (DTCG) -> array: mutating every returned token does not modify the input', () => {
    const tokens = makeDtcgObject();
    const before = structuredClone(tokens);
    const result = convertTokenData(tokens, { output: 'array', usesDtcg: true });
    expect(Array.isArray(result)).to.be.true;
    expect(result.length).to.eql(3);
    result.forEach(mutateNested);
    expect(tokens).to.eql(before);
  });
});

import { expect } from 'chai';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

// Load the implementation under test from the workspace root so this test
// works regardless of where the runner places this file.
const { convertTokenData } = await import(
  pathToFileURL(join(process.cwd(), 'lib/utils/convertTokenData.js')).href
);

const INPUTS = ['object', 'map', 'array'];
const OUTPUTS = ['object', 'map', 'array'];
const NESTED_PROPS = ['value', 'attributes', 'original', 'path'];

function makeObject() {
  return {
    color: {
      red: {
        value: { r: 255, g: 0, b: 0 },
        attributes: { category: 'color' },
        original: { value: { r: 255, g: 0, b: 0 } },
        path: ['color', 'red'],
        key: '{color.red}',
      },
      green: {
        value: { r: 0, g: 255, b: 0 },
        attributes: { category: 'color' },
        original: { value: { r: 0, g: 255, b: 0 } },
        path: ['color', 'green'],
        key: '{color.green}',
      },
    },
    spacing: {
      base: {
        value: { size: 4, unit: 'px' },
        attributes: { category: 'spacing' },
        original: { value: { size: 4, unit: 'px' } },
        path: ['spacing', 'base'],
        key: '{spacing.base}',
      },
    },
  };
}

function makeArray() {
  const object = makeObject();
  return [object.color.red, object.color.green, object.spacing.base];
}

function makeMap() {
  return new Map(makeArray().map((token) => [token.key, token]));
}

const FACTORIES = { object: makeObject, map: makeMap, array: makeArray };

// Collect every token contained in a collection of any of the 3 supported shapes.
function tokensIn(collection, type) {
  if (type === 'array') {
    return collection.slice();
  }
  if (type === 'map') {
    return Array.from(collection.values());
  }
  const found = [];
  const walk = (node) => {
    if (node === null || typeof node !== 'object') {
      return;
    }
    if (Object.hasOwn(node, 'value') || Object.hasOwn(node, '$value')) {
      found.push(node);
      return;
    }
    for (const k of Object.keys(node)) {
      walk(node[k]);
    }
  };
  for (const k of Object.keys(collection)) {
    walk(collection[k]);
  }
  return found;
}

function byKey(tokens) {
  return new Map(tokens.map((token) => [token.key, token]));
}

// Mutate nested sub-properties of a token the way an accidental caller would.
function mutateNested(token) {
  for (const prop of ['value', '$value', 'attributes', 'original', 'path']) {
    const nested = token[prop];
    if (Array.isArray(nested)) {
      nested.push('mutated');
    } else if (nested !== null && typeof nested === 'object') {
      nested.injected = 'mutated';
    }
  }
}

describe('convertTokenData result tokens never alias the input collection or each other', () => {
  INPUTS.forEach((input) => {
    OUTPUTS.forEach((output) => {
      it(`${input} -> ${output}: result tokens share no identity or nested structures with input tokens`, () => {
        const tokens = FACTORIES[input]();
        const result = convertTokenData(tokens, { output, usesDtcg: false });

        const inputTokens = tokensIn(tokens, input);
        const resultTokens = tokensIn(result, output);
        const inputByKey = byKey(inputTokens);

        expect(resultTokens.length).to.eql(inputByKey.size);

        for (const resultToken of resultTokens) {
          const inputToken = inputByKey.get(resultToken.key);
          expect(inputToken, `input must contain token ${resultToken.key}`).to.exist;

          expect(resultToken, `${input}->${output} token ${resultToken.key}`).to.not.equal(
            inputToken,
          );
          for (const prop of NESTED_PROPS) {
            const nested = inputToken[prop];
            if (nested !== null && typeof nested === 'object') {
              expect(
                resultToken[prop],
                `${input}->${output} ${resultToken.key}.${prop}`,
              ).to.not.equal(nested);
            }
          }
        }
      });

      it(`${input} -> ${output}: mutating one result token leaves input and sibling result tokens unchanged`, () => {
        const tokens = FACTORIES[input]();
        const inputBefore = structuredClone(tokens);
        const result = convertTokenData(tokens, { output, usesDtcg: false });

        const resultTokens = tokensIn(result, output);
        const target = resultTokens[0];
        const siblingsBefore = structuredClone(resultTokens.slice(1));

        mutateNested(target);

        expect(tokens).to.eql(inputBefore);
        expect(resultTokens.slice(1)).to.eql(siblingsBefore);
      });

      it(`${input} -> ${output}: mutating the input afterwards leaves the result tokens unchanged`, () => {
        const tokens = FACTORIES[input]();
        const result = convertTokenData(tokens, { output, usesDtcg: false });
        const resultBefore = structuredClone(result);

        mutateNested(tokensIn(tokens, input)[0]);

        expect(result).to.eql(resultBefore);
      });
    });
  });
});

import { expect } from 'chai';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

// Load the implementations under test from the workspace root so this test
// works regardless of where the runner places this file.
const root = process.cwd();
const { default: flattenTokens } = await import(
  pathToFileURL(join(root, 'lib/utils/flattenTokens.js')).href
);
const { convertTokenData } = await import(
  pathToFileURL(join(root, 'lib/utils/convertTokenData.js')).href
);

// Existing conversion fixtures: each shape represents the same token data,
// so every object/map/array conversion must keep producing deeply equal results.
const normal = {
  object: {
    colors: {
      red: { 500: { value: '#f00', foo: 'bar', key: '{colors.red.500}' } },
      green: { 500: { value: '#0f0', foo: 'baz', key: '{colors.green.500}' } },
      blue: { 500: { value: '#00f', foo: 'qux', key: '{colors.blue.500}' } },
    },
  },
  array: [
    { value: '#f00', foo: 'bar', key: '{colors.red.500}' },
    { value: '#0f0', foo: 'baz', key: '{colors.green.500}' },
    { value: '#00f', foo: 'qux', key: '{colors.blue.500}' },
  ],
  map: new Map([
    ['{colors.red.500}', { value: '#f00', foo: 'bar', key: '{colors.red.500}' }],
    ['{colors.green.500}', { value: '#0f0', foo: 'baz', key: '{colors.green.500}' }],
    ['{colors.blue.500}', { value: '#00f', foo: 'qux', key: '{colors.blue.500}' }],
  ]),
};

const dtcg = {
  object: {
    colors: {
      red: { 500: { $value: '#f00', foo: 'bar', key: '{colors.red.500}' } },
      green: { 500: { $value: '#0f0', foo: 'baz', key: '{colors.green.500}' } },
      blue: { 500: { $value: '#00f', foo: 'qux', key: '{colors.blue.500}' } },
    },
  },
  array: [
    { $value: '#f00', foo: 'bar', key: '{colors.red.500}' },
    { $value: '#0f0', foo: 'baz', key: '{colors.green.500}' },
    { $value: '#00f', foo: 'qux', key: '{colors.blue.500}' },
  ],
  map: new Map([
    ['{colors.red.500}', { $value: '#f00', foo: 'bar', key: '{colors.red.500}' }],
    ['{colors.green.500}', { $value: '#0f0', foo: 'baz', key: '{colors.green.500}' }],
    ['{colors.blue.500}', { $value: '#00f', foo: 'qux', key: '{colors.blue.500}' }],
  ]),
};

const SHAPES = ['object', 'map', 'array'];

describe('convertTokenData existing conversion results are preserved', () => {
  [
    { mode: 'normal', data: normal, usesDtcg: false },
    { mode: 'DTCG', data: dtcg, usesDtcg: true },
  ].forEach(({ mode, data, usesDtcg }) => {
    describe(`${mode} tokens`, () => {
      SHAPES.forEach((output) => {
        SHAPES.forEach((input) => {
          it(`converts ${input} to ${output} deeply equal to the previous result`, () => {
            const source = structuredClone(data[input]);
            const result = convertTokenData(source, { output, usesDtcg });
            expect(result).to.eql(data[output]);
          });
        });
      });
    });
  });

  describe('round-trips', () => {
    it('normal: object -> array -> object round-trips deeply equal', () => {
      const array = convertTokenData(structuredClone(normal.object), {
        output: 'array',
        usesDtcg: false,
      });
      expect(array).to.eql(normal.array);
      const back = convertTokenData(array, { output: 'object', usesDtcg: false });
      expect(back).to.eql(normal.object);
    });

    it('normal: map -> array -> map round-trips deeply equal', () => {
      const array = convertTokenData(structuredClone(normal.map), {
        output: 'array',
        usesDtcg: false,
      });
      expect(array).to.eql(normal.array);
      const back = convertTokenData(array, { output: 'map', usesDtcg: false });
      expect(back).to.eql(normal.map);
    });

    it('normal: array -> map -> array round-trips deeply equal', () => {
      const map = convertTokenData(structuredClone(normal.array), {
        output: 'map',
        usesDtcg: false,
      });
      expect(map).to.eql(normal.map);
      const back = convertTokenData(map, { output: 'array', usesDtcg: false });
      expect(back).to.eql(normal.array);
    });

    it('DTCG: object -> array -> object round-trips deeply equal', () => {
      const array = convertTokenData(structuredClone(dtcg.object), {
        output: 'array',
        usesDtcg: true,
      });
      expect(array).to.eql(dtcg.array);
      const back = convertTokenData(array, { output: 'object', usesDtcg: true });
      expect(back).to.eql(dtcg.object);
    });
  });

  describe('token syntax detection', () => {
    it('flattenTokens finds non-DTCG "value" tokens', () => {
      expect(flattenTokens(structuredClone(normal.object))).to.eql(normal.array);
    });

    it('flattenTokens finds DTCG "$value" tokens when usesDtcg is true', () => {
      expect(flattenTokens(structuredClone(dtcg.object), true)).to.eql(dtcg.array);
    });
  });

  it('still protects against prototype pollution from malicious token keys', () => {
    const maliciousKeys = [
      '{__proto__.a}',
      '{constructor.prototype.a}',
      '{prototype.a}',
      '{nested.object.constructor.prototype.a}',
      '{nested.object.prototype.a}',
      '{nested.object.__proto__.a}',
    ];
    for (const key of maliciousKeys) {
      convertTokenData([{ key, value: 'b' }], { output: 'object', usesDtcg: false });
      expect({}.a, `prototype polluted by key ${key}`).to.be.undefined;
    }
  });
});
